43	public class TensorFlowImporter {
44	
45	    private static final Logger log = Logger.getLogger(TensorFlowImporter.class.getName());
46	
47	    /**
48	     * Imports a saved TensorFlow model from a directory.
49	     * The model should be saved as a .pbtxt or .pb file.
50	     * The name of the model is taken as the db/pbtxt file name (not including the file ending).
51	     *
52	     * @param modelDir the directory containing the TensorFlow model files to import
53	     */
54	    public TensorFlowModel importModel(String modelDir) {
55	        try (SavedModelBundle model = SavedModelBundle.load(modelDir, "serve")) {
56	            return importModel(model);
57	        }
58	        catch (IllegalArgumentException e) {
59	            throw new IllegalArgumentException("Could not import TensorFlow model from directory '" + modelDir + "'", e);
60	        }
61	    }
62	
63	    public TensorFlowModel importModel(File modelDir) {
64	        return importModel(modelDir.toString());
65	    }
66	
67	    /** Imports a TensorFlow model */
68	    public TensorFlowModel importModel(SavedModelBundle model) {
69	        try {
70	            return importGraph(MetaGraphDef.parseFrom(model.metaGraphDef()), model);
71	        }
72	        catch (IOException e) {
73	            throw new IllegalArgumentException("Could not import TensorFlow model '" + model + "'", e);
74	        }
75	    }
76	
77	    /**
78	     * Imports the TensorFlow graph by first importing the tensor types, then
79	     * finding a suitable set of dimensions names for each
80	     * placeholder/constant/variable, then importing the expressions.
81	     */
82	    private static TensorFlowModel importGraph(MetaGraphDef graph, SavedModelBundle bundle) {
83	        TensorFlowModel model = new TensorFlowModel();
84	        OperationIndex index = new OperationIndex();
85	
86	        importSignatures(graph, model);
87	        importNodes(graph, model, index);
88	        findDimensionNames(model, index);
89	        importExpressions(model, index, bundle);
90	
91	        reportWarnings(model, index);
92	        logVariableTypes(index);
93	
94	        return model;
95	    }
96	
97	    private static void importSignatures(MetaGraphDef graph, TensorFlowModel model) {
98	        for (Map.Entry<String, SignatureDef> signatureEntry : graph.getSignatureDefMap().entrySet()) {
99	            String signatureName = signatureEntry.getKey();
100	            TensorFlowModel.Signature signature = model.signature(signatureName);
101	
102	            Map<String, TensorInfo> inputInfoMap = signatureEntry.getValue().getInputsMap();
103	            for (Map.Entry<String, TensorInfo> input : inputInfoMap.entrySet()) {
104	                String inputName = input.getKey();
105	                signature.input(inputName, namePartOf(input.getValue().getName()));
106	            }
107	
108	            Map<String, TensorInfo> outputInfoMap = signatureEntry.getValue().getOutputsMap();
109	            for (Map.Entry<String, TensorInfo> output : outputInfoMap.entrySet()) {
110	                String outputName = output.getKey();
111	                signature.output(outputName, namePartOf(output.getValue().getName()));
112	            }
113	        }
114	    }
115	
116	    private static boolean isSignatureInput(TensorFlowModel model, TensorFlowOperation operation) {
117	        for (TensorFlowModel.Signature signature : model.signatures().values()) {
118	            for (String inputName : signature.inputs().values()) {
119	                if (inputName.equals(operation.node().getName())) {
120	                    return true;
121	                }
122	            }
123	        }
124	        return false;
125	    }
