128	        for (TensorFlowModel.Signature signature : model.signatures().values()) {
129	            for (String outputName : signature.outputs().values()) {
130	                if (outputName.equals(operation.node().getName())) {
131	                    return true;
132	                }
133	            }
134	        }
135	        return false;
