20	
21	        // Check required macros
22	        assertEquals(1, model.get().requiredMacros().size());
23	        assertTrue(model.get().requiredMacros().containsKey("X"));
24	        assertEquals(new TensorType.Builder().indexed("d0").indexed("d1", 784).build(),
