2	package com.yahoo.searchlib.rankingexpression.integration.tensorflow;
3	
4	import com.yahoo.searchlib.rankingexpression.RankingExpression;
5	import com.yahoo.searchlib.rankingexpression.evaluation.Context;
6	import com.yahoo.searchlib.rankingexpression.evaluation.MapContext;
7	import com.yahoo.searchlib.rankingexpression.evaluation.TensorValue;
8	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.TensorConverter;
9	import com.yahoo.searchlib.rankingexpression.rule.CompositeNode;
10	import com.yahoo.searchlib.rankingexpression.rule.ExpressionNode;
11	import com.yahoo.searchlib.rankingexpression.rule.ReferenceNode;
12	import com.yahoo.tensor.Tensor;
13	import com.yahoo.tensor.TensorType;
14	import org.tensorflow.SavedModelBundle;
15	import org.tensorflow.Session;
16	
17	import java.nio.FloatBuffer;
18	import java.util.List;
19	
20	import static org.junit.Assert.assertEquals;
21	
22	/**
23	 * Helper for TensorFlow import tests: Imports a model and provides asserts on it.
24	 * This currently assumes the TensorFlow model takes a single input of type tensor(d0[1],d1[784])
25	 *
26	 * @author bratseth
27	 */
28	public class TestableTensorFlowModel {
29	
30	    private SavedModelBundle tensorFlowModel;
31	    private TensorFlowModel model;
32	
33	    // Sizes of the input vector
34	    private final int d0Size = 1;
35	    private final int d1Size = 784;
36	
37	    public TestableTensorFlowModel(String modelDir) {
38	        tensorFlowModel = SavedModelBundle.load(modelDir, "serve");
39	        model = new TensorFlowImporter().importModel(tensorFlowModel);
40	    }
41	
42	    public TensorFlowModel get() { return model; }
43	
44	    public void assertEqualResult(String inputName, String operationName) {
45	        Tensor tfResult = tensorFlowExecute(tensorFlowModel, inputName, operationName);
46	        Context context = contextFrom(model);
47	        Tensor placeholder = placeholderArgument();
48	        context.put(inputName, new TensorValue(placeholder));
49	
50	        model.macros().forEach((k,v) -> evaluateMacro(context, model, k));
51	
52	        Tensor vespaResult = model.expressions().get(operationName).evaluate(context).asTensor();
53	        assertEquals("Operation '" + operationName + "' produces equal results", tfResult, vespaResult);
54	    }
55	
56	    private Tensor tensorFlowExecute(SavedModelBundle model, String inputName, String operationName) {
57	        Session.Runner runner = model.session().runner();
58	        FloatBuffer fb = FloatBuffer.allocate(d0Size * d1Size);
59	        for (int i = 0; i < d1Size; ++i) {
60	            fb.put(i, (float)(i * 1.0 / d1Size));
61	        }
62	        org.tensorflow.Tensor<?> placeholder = org.tensorflow.Tensor.create(new long[]{ d0Size, d1Size }, fb);
63	        runner.feed(inputName, placeholder);
64	        List<org.tensorflow.Tensor<?>> results = runner.fetch(operationName).run();
65	        assertEquals(1, results.size());
66	        return TensorConverter.toVespaTensor(results.get(0));
67	    }
68	
69	    private Context contextFrom(TensorFlowModel result) {
70	        MapContext context = new MapContext();
71	        result.largeConstants().forEach((name, tensor) -> context.put("constant(" + name + ")", new TensorValue(tensor)));
72	        result.smallConstants().forEach((name, tensor) -> context.put("constant(" + name + ")", new TensorValue(tensor)));
73	        return context;
74	    }
75	
76	    private Tensor placeholderArgument() {
77	        Tensor.Builder b = Tensor.Builder.of(new TensorType.Builder().indexed("d0", d0Size).indexed("d1", d1Size).build());
78	        for (int d0 = 0; d0 < d0Size; d0++)
79	            for (int d1 = 0; d1 < d1Size; d1++)
80	                b.cell(d1 * 1.0 / d1Size, d0, d1);
81	        return b.build();
82	    }
83	
84	    private void evaluateMacro(Context context, TensorFlowModel model, String macroName) {
85	        if (!context.names().contains(macroName)) {
86	            RankingExpression e = model.macros().get(macroName);
87	            evaluateMacroDependencies(context, model, e.getRoot());
88	            context.put(macroName, new TensorValue(e.evaluate(context).asTensor()));
89	        }
90	    }
91	
92	    private void evaluateMacroDependencies(Context context, TensorFlowModel model, ExpressionNode node) {
93	        if (node instanceof ReferenceNode) {
94	            String name = node.toString();
95	            if (model.macros().containsKey(name)) {
96	                evaluateMacro(context, model, name);
97	            }
98	        }
99	        else if (node instanceof CompositeNode) {
100	            for (ExpressionNode child : ((CompositeNode)node).children()) {
101	                evaluateMacroDependencies(context, model, child);
102	            }
103	        }
104	    }
105	
106	}
107

