14	/**
15	 * The result of importing a TensorFlow model into Vespa.
16	 * - A set of signatures which are named collections of inputs and outputs.
17	 * - A set of named constant tensors represented by Variable nodes in TensorFlow.
18	 * - A list of warning messages.
19	 *
20	 * @author bratseth
21	 */
22	// This object can be built incrementally within this package, but is immutable when observed from outside the package
23	public class TensorFlowModel {
24	
25	    private final Map<String, Signature> signatures = new HashMap<>();
26	    private final Map<String, TensorType> arguments = new HashMap<>();
27	    private final Map<String, Tensor> smallConstants = new HashMap<>();
28	    private final Map<String, Tensor> largeConstants = new HashMap<>();
29	    private final Map<String, RankingExpression> expressions = new HashMap<>();
30	    private final Map<String, RankingExpression> macros = new HashMap<>();
31	    private final Map<String, TensorType> requiredMacros = new HashMap<>();
32	
33	    void argument(String name, TensorType argumentType) { arguments.put(name, argumentType); }
34	    void smallConstant(String name, Tensor constant) { smallConstants.put(name, constant); }
35	    void largeConstant(String name, Tensor constant) { largeConstants.put(name, constant); }
36	    void expression(String name, RankingExpression expression) { expressions.put(name, expression); }
37	    void macro(String name, RankingExpression expression) { macros.put(name, expression); }
38	    void requiredMacro(String name, TensorType type) { requiredMacros.put(name, type); }
39	
40	    /** Returns the given signature. If it does not already exist it is added to this. */
41	    Signature signature(String name) {
42	        return signatures.computeIfAbsent(name, Signature::new);
43	    }
44	
45	    /** Returns an immutable map of the arguments ("Placeholders") of this */
46	    public Map<String, TensorType> arguments() { return Collections.unmodifiableMap(arguments); }
47	
48	    /**
49	     * Returns an immutable map of the small constants of this.
50	     * These should have sizes up to a few kb at most, and correspond to constant
51	     * values given in the TensorFlow source.
52	     */
53	    public Map<String, Tensor> smallConstants() { return Collections.unmodifiableMap(smallConstants); }
54	
55	    /**
56	     * Returns an immutable map of the large constants of this.
57	     * These can have sizes in gigabytes and must be distributed to nodes separately from configuration,
58	     * and correspond to Variable files stored separately in TensorFlow.
59	     */
60	    public Map<String, Tensor> largeConstants() { return Collections.unmodifiableMap(largeConstants); }
61	
62	    /**
63	     * Returns an immutable map of the expressions of this - corresponding to TensorFlow nodes
64	     * which are not Placeholders or Variables (which instead become respectively arguments and constants).
65	     * Note that only nodes recursively referenced by a placeholder are added.
66	     */
67	    public Map<String, RankingExpression> expressions() { return Collections.unmodifiableMap(expressions); }
68	
69	    /** Returns an immutable map of macros that are part of this model */
70	    public Map<String, RankingExpression> macros() { return Collections.unmodifiableMap(macros); }
71	
72	    /** Returns an immutable map of the macros that must be provided by the environment running this model */
73	    public Map<String, TensorType> requiredMacros() { return Collections.unmodifiableMap(requiredMacros); }
74	
75	    /** Returns an immutable map of the signatures of this */
76	    public Map<String, Signature> signatures() { return Collections.unmodifiableMap(signatures); }
77	
78	    /**
79	     * A signature is a set of named inputs and outputs, where the inputs maps to argument ("placeholder") names+types,
80	     * and outputs maps to expressions nodes.
81	     */
82	    public class Signature {
83	
84	        private final String name;
85	        private final Map<String, String> inputs = new HashMap<>();
86	        private final Map<String, String> outputs = new HashMap<>();
87	        private final Map<String, String> skippedOutputs = new HashMap<>();
88	        private final List<String> importWarnings = new ArrayList<>();
89	
90	        Signature(String name) {
91	            this.name = name;
92	        }
93	
94	        void input(String inputName, String argumentName) { inputs.put(inputName, argumentName); }
95	        void output(String name, String expressionName) { outputs.put(name, expressionName); }
96	        void skippedOutput(String name, String reason) { skippedOutputs.put(name, reason); }
97	        void importWarning(String warning) { importWarnings.add(warning); }
98	
99	        public String name() { return name; }
100	
101	        /** Returns the result this is part of */
102	        TensorFlowModel owner() { return TensorFlowModel.this; }
103	
104	        /**
105	         * Returns an immutable map of the inputs (evaluation context) of this. This is a map from input name
106	         * to argument (Placeholder) name in the owner of this
107	         */
108	        public Map<String, String> inputs() { return Collections.unmodifiableMap(inputs); }
109	
110	        /** Returns owner().arguments().get(inputs.get(name)), e.g the type of the argument this input references */
111	        public TensorType inputArgument(String inputName) { return owner().arguments().get(inputs.get(inputName)); }
112	
113	        /** Returns an immutable list of the expression names of this */
114	        public Map<String, String> outputs() { return Collections.unmodifiableMap(outputs); }
115	
116	        /**
117	         * Returns an immutable list of the outputs of this which could not be imported,
118	         * with a string detailing the reason for each
119	         */
120	        public Map<String, String> skippedOutputs() { return Collections.unmodifiableMap(skippedOutputs); }
121	
122	        /**
123	         * Returns an immutable list of possibly non-fatal warnings encountered during import.
124	         */
125	        public List<String> importWarnings() { return Collections.unmodifiableList(importWarnings); }
126	
127	        /** Returns owner().expressions().get(outputs.get(outputName)), e.g the expression this output references */
128	        public RankingExpression outputExpression(String outputName) { return owner().expressions().get(outputs.get(outputName)); }
