2	package com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.operations;
3	
4	import com.yahoo.searchlib.rankingexpression.Reference;
5	import com.yahoo.searchlib.rankingexpression.evaluation.BooleanValue;
6	import com.yahoo.searchlib.rankingexpression.evaluation.DoubleValue;
7	import com.yahoo.searchlib.rankingexpression.evaluation.TensorValue;
8	import com.yahoo.searchlib.rankingexpression.evaluation.Value;
9	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.DimensionRenamer;
10	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.OrderedTensorType;
11	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.TensorConverter;
12	import com.yahoo.searchlib.rankingexpression.rule.ConstantNode;
13	import com.yahoo.searchlib.rankingexpression.rule.ExpressionNode;
14	import com.yahoo.searchlib.rankingexpression.rule.ReferenceNode;
15	import com.yahoo.searchlib.rankingexpression.rule.TensorFunctionNode;
16	import com.yahoo.tensor.TensorType;
17	import com.yahoo.tensor.functions.TensorFunction;
18	import org.tensorflow.framework.AttrValue;
19	import org.tensorflow.framework.NodeDef;
20	
21	import java.util.List;
22	import java.util.Optional;
23	
24	public class Const extends TensorFlowOperation {
25	
26	    public Const(NodeDef node, List<TensorFlowOperation> inputs, int port) {
27	        super(node, inputs, port);
28	        setConstantValue(value());
29	    }
30	
31	    @Override
32	    protected OrderedTensorType lazyGetType() {
33	        return OrderedTensorType.fromTensorFlowType(node, vespaName() + "_");
34	    }
35	
36	    @Override
37	    public Optional<TensorFunction> function() {
38	        if (function == null) {
39	            function = lazyGetFunction();
40	        }
41	        return Optional.ofNullable(function);
42	    }
43	
44	    @Override
45	    protected TensorFunction lazyGetFunction() {
46	        ExpressionNode expressionNode;
47	        if (type.type().rank() == 0 && getConstantValue().isPresent()) {
48	            expressionNode = new ConstantNode(getConstantValue().get().asDoubleValue());
49	        } else {
50	            expressionNode = new ReferenceNode(Reference.simple("constant", vespaName()));
51	        }
52	        return new TensorFunctionNode.TensorFunctionExpressionNode(expressionNode);
53	    }
54	
55	    @Override
56	    public void addDimensionNameConstraints(DimensionRenamer renamer) {
57	        for (TensorType.Dimension dimension : type.type().dimensions()) {
58	            renamer.addDimension(dimension.name());
59	        }
60	    }
61	
62	    @Override
63	    public void renameDimensions(DimensionRenamer renamer) {
64	        super.renameDimensions(renamer);
65	        setConstantValue(value());
66	    }
67	
68	    @Override
69	    public boolean isConstant() {
70	        return true;
71	    }
72	
73	    private Value value() {
74	        if (!node.getAttrMap().containsKey("value")) {
75	            throw new IllegalArgumentException("Node '" + node.getName() + "' of type " +
76	                                               "const has missing 'value' attribute");
77	        }
78	        AttrValue attrValue = node.getAttrMap().get("value");
79	        if (attrValue.getValueCase() == AttrValue.ValueCase.TENSOR) {
80	            return new TensorValue(TensorConverter.toVespaTensor(attrValue.getTensor(), type().get().type()));
81	        }
82	        if (attrValue.getValueCase() == AttrValue.ValueCase.B) {
83	            return new BooleanValue(attrValue.getB());
84	        }
85	        if (attrValue.getValueCase() == AttrValue.ValueCase.I) {
86	            return new DoubleValue(attrValue.getI());
87	        }
88	        if (attrValue.getValueCase() == AttrValue.ValueCase.F) {
89	            return new DoubleValue(attrValue.getF());
90	        }
91	        throw new IllegalArgumentException("Requesting value of constant in " +
92	                node.getName() + " but type is not recognized.");
93	    }
