17	 * A Vespa tensor type is ordered by the lexicographical ordering of dimension
18	 * names. TensorFlow tensors have an explicit ordering of their dimensions.
19	 * During import, we need to track the Vespa dimension that matches the
20	 * corresponding TensorFlow dimension as the ordering can change after
21	 * dimension renaming. That is the purpose of this class.
22	 *
23	 * @author lesters
24	 */
25	public class OrderedTensorType {
26	
27	    private final TensorType type;
28	    private final List<TensorType.Dimension> dimensions;
29	
30	    private final long[] innerSizesTensorFlow;
31	    private final long[] innerSizesVespa;
32	    private final int[] dimensionMap;
33	
34	    private OrderedTensorType(List<TensorType.Dimension> dimensions) {
35	        this.dimensions = Collections.unmodifiableList(dimensions);
36	        this.type = new TensorType.Builder(dimensions).build();
37	        this.innerSizesTensorFlow = new long[dimensions.size()];
38	        this.innerSizesVespa = new long[dimensions.size()];
39	        this.dimensionMap = createDimensionMap();
40	    }
41	
