82	     * When dimension ordering between Vespa and TensorFlow differs, i.e.
83	     * after dimension renaming, use the dimension map to read in values
84	     * so that they are correctly laid out in memory for Vespa.
85	     * Used when importing tensors from TensorFlow.
86	     */
87	    public int toDirectIndex(int index) {
88	        if (dimensions.size() == 0) {
89	            return 0;
90	        }
91	        if (dimensionMap == null)  {
92	            throw new IllegalArgumentException("Dimension map is not available");
93	        }
94	        int directIndex = 0;
95	        long rest = index;
96	        for (int i = 0; i < dimensions.size(); ++i) {
97	            long address = rest / innerSizesTensorFlow[i];
98	            directIndex += innerSizesVespa[dimensionMap[i]] * address;
99	            rest %= innerSizesTensorFlow[i];
100	        }
101	        return directIndex;
102	    }
