157	        List<TensorType.Dimension> renamedDimensions = new ArrayList<>(dimensions.size());
158	        for (TensorType.Dimension dimension : dimensions) {
159	            String oldName = dimension.name();
160	            Optional<String> newName = renamer.dimensionNameOf(oldName);
161	            if (!newName.isPresent())
